//! Follow the theme generated by DMS for Zed, including its alpha channels.

mod source;

use gpui_kit::{
    App, Global, Pixels, Task, Window, WindowBackgroundAppearance,
    component::{Theme, ThemeConfig, ThemeMode},
    px,
};
use source::{Files, Sources};
use std::{path::PathBuf, rc::Rc, time::Duration};

const REFRESH_INTERVAL: Duration = Duration::from_secs(1);
const CONTENT_OPACITY: f32 = 0.94;
const CONTENT_FONT_SCALE: f32 = 0.875;
pub(super) const CONTENT_LINE_HEIGHT: f32 = 1.6;

pub(super) fn content_font_size(cx: &App) -> Pixels {
    cx.try_global::<Appearance>()
        .and_then(|appearance| appearance.content_font_size)
        .map(px)
        .unwrap_or_else(|| {
            px((f32::from(Theme::global(cx).font_size) * CONTENT_FONT_SCALE).round())
        })
}

pub(super) fn content_background(cx: &App) -> gpui_kit::Hsla {
    let mut color = Theme::global(cx).background;
    color.a = CONTENT_OPACITY;
    color
}

#[derive(Clone)]
struct WatchConfig(Sources);
impl Global for WatchConfig {}

#[derive(Clone)]
pub(super) struct Appearance {
    pub name: String,
    pub background: WindowBackgroundAppearance,
    pub content_font_size: Option<f32>,
    pub font_fallbacks: gpui_kit::FontFallbacks,
}
impl Global for Appearance {}

pub(super) fn init(theme_file: Option<PathBuf>, cx: &mut App) {
    let sources = Sources::discover(theme_file);
    let files = sources.read();
    let dark = ThemeMode::from(cx.window_appearance()).is_dark();
    apply(&files, dark, None, cx);
    cx.set_global(WatchConfig(sources));
}

pub(super) fn watch(window: &mut Window, cx: &mut App) -> Task<()> {
    let sources = cx.global::<WatchConfig>().0.clone();
    window.spawn(cx, async move |cx| {
        let mut previous = None;
        loop {
            let source = sources.clone();
            let files = cx
                .background_executor()
                .spawn(async move { source.read() })
                .await;
            if cx
                .update(|window, cx| {
                    let dark = ThemeMode::from(window.appearance()).is_dark();
                    if previous.as_ref() != Some(&(files.clone(), dark)) {
                        apply(&files, dark, Some(window), cx);
                        previous = Some((files, dark));
                    }
                })
                .is_err()
            {
                break;
            }
            cx.background_executor().timer(REFRESH_INTERVAL).await;
        }
    })
}

fn apply(files: &Files, dark: bool, window: Option<&mut Window>, cx: &mut App) {
    let mut resolved = match source::resolve(files, dark) {
        Ok(resolved) => resolved,
        Err(error) => {
            tracing::warn!(%error, "cannot reload desktop theme; keeping the current palette");
            if cx.has_global::<Appearance>() {
                return;
            }
            source::fallback(dark)
        }
    };
    resolved.background = WindowBackgroundAppearance::Blurred;
    let mut config: ThemeConfig = resolved.config;
    let fonts = cx.text_system().all_font_names();
    let preferred = config.font_family.take();
    config.font_family = preferred
        .filter(|family| fonts.iter().any(|font| font == family.as_ref()))
        .or_else(|| {
            ["Inter", "Inter Variable", "Noto Sans", "Noto Sans CJK SC"]
                .into_iter()
                .find(|name| fonts.iter().any(|font| font == name))
                .map(Into::into)
        });
    if config
        .mono_font_family
        .as_ref()
        .is_some_and(|family| !fonts.iter().any(|font| font == family.as_ref()))
    {
        config.mono_font_family = None;
    }
    resolved.font_fallbacks.retain(|family| fonts.contains(family));
    // Prefer static CJK faces: variable Noto CJK can resolve to its thin default
    // axis in the Linux text backend. Keep the requested weight and size.
    for family in [
        "Sarasa UI SC",
        "Noto Sans CJK SC",
        "Source Han Sans SC",
        "PingFang SC",
        "Microsoft YaHei",
    ] {
        if fonts.iter().any(|font| font == family) {
            resolved.font_fallbacks.push(family.to_owned());
            break;
        }
    }
    tracing::debug!(family = ?config.font_family, fallbacks = ?resolved.font_fallbacks, "resolved UI font families");
    let mode = config.mode;
    let config = Rc::new(config);
    let theme = Theme::global_mut(cx);
    if mode.is_dark() {
        theme.dark_theme = config;
    } else {
        theme.light_theme = config;
    }
    cx.set_global(Appearance {
        name: resolved.name,
        background: resolved.background,
        content_font_size: resolved.content_font_size,
        font_fallbacks: gpui_kit::FontFallbacks::from_fonts(resolved.font_fallbacks),
    });
    if let Some(window) = window {
        window.set_background_appearance(resolved.background);
        Theme::change(mode, Some(window), cx);
    } else {
        Theme::change(mode, None, cx);
    }
}

pub(super) fn font_style(cx: &App) -> gpui_kit::StyleRefinement {
    let mut style = gpui_kit::StyleRefinement::default();
    style.text.font_fallbacks = cx
        .try_global::<Appearance>()
        .map(|appearance| appearance.font_fallbacks.clone());
    style
}
